def column_totals(rows):
    if not rows:
        return []
    result = []
    num_cols = len(rows[0])
    for i in range(num_cols):
        total = 0
        numeric_found = False
        for row in rows:
            if i < len(row):
                val = row[i]
                if isinstance(val, (int, float)):
                    total += val
                    numeric_found = True
        if numeric_found:
            result.append(total)
        else:
            result.append("")
    return result

